import type { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';

/** A job runs at most this many times in total (the first attempt plus two retries). */
export const MAX_ATTEMPTS = 3;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_STALE_MS = 3000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface JobRow {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed_steps: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type CreateOutcome =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed_steps, total: r.steps },
    result: r.status === 'completed' ? { output: r.output ?? '' } : null,
    error: r.status === 'failed' ? (r.error ?? 'transient failure') : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** All reads and writes of job state. Used by both the server and the worker. */
export class JobStore {
  constructor(private readonly db: DatabaseSync) {}

  /** Runs `fn` inside a write transaction. BEGIN IMMEDIATE takes the write lock up front. */
  private tx<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    try {
      const result = fn();
      this.db.exec('COMMIT');
      return result;
    } catch (e) {
      this.db.exec('ROLLBACK');
      throw e;
    }
  }

  private jobRow(id: string): JobRow | undefined {
    return this.db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
  }

  getJob(id: string): Job | undefined {
    const row = this.jobRow(id);
    return row && toJob(row);
  }

  /** Newest first. */
  listJobs(): Job[] {
    return (this.db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toJob);
  }

  /** Creates a job. With an idempotency key, a replay returns the original job and a mismatch is a conflict. */
  createJob(job: NewJob, idempotency?: { key: string; fingerprint: string }): CreateOutcome {
    return this.tx<CreateOutcome>(() => {
      if (idempotency) {
        const prior = this.db
          .prepare('SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?')
          .get(idempotency.key) as unknown as { fingerprint: string; job_id: string } | undefined;
        if (prior) {
          if (prior.fingerprint !== idempotency.fingerprint) return { kind: 'conflict' };
          const existing = this.getJob(prior.job_id);
          if (existing) return { kind: 'replayed', job: existing };
        }
      }
      const id = randomUUID();
      const now = new Date().toISOString();
      this.db
        .prepare(
          `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed_steps, output, error, run_after, created_at, updated_at)
           VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, 0, ?, ?)`,
        )
        .run(id, job.input, job.steps, job.failAttempts, now, now);
      if (idempotency) {
        this.db
          .prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)')
          .run(idempotency.key, idempotency.fingerprint, id);
      }
      return { kind: 'created', job: this.getJob(id) as Job };
    });
  }

  /** Takes the oldest queued job that is due, marks it running and counts the new attempt. */
  claimNext(now: number): Job | undefined {
    return this.tx(() => {
      const row = this.db
        .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`)
        .get(now) as unknown as { id: string } | undefined;
      if (!row) return undefined;
      this.db
        .prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0, updated_at = ? WHERE id = ?`)
        .run(new Date().toISOString(), row.id);
      return this.getJob(row.id);
    });
  }

  setProgress(id: string, completed: number): void {
    this.db
      .prepare(`UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(completed, new Date().toISOString(), id);
  }

  /** Puts a failed attempt back in the queue, due at `runAfter` (epoch ms). */
  scheduleRetry(id: string, runAfter: number): void {
    this.db
      .prepare(`UPDATE jobs SET status = 'queued', completed_steps = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(runAfter, new Date().toISOString(), id);
  }

  completeJob(id: string, output: string): void {
    this.db
      .prepare(
        `UPDATE jobs SET status = 'completed', output = ?, error = NULL, completed_steps = steps, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      )
      .run(output, new Date().toISOString(), id);
  }

  failJob(id: string, error: string): void {
    this.db
      .prepare(`UPDATE jobs SET status = 'failed', output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(error, new Date().toISOString(), id);
  }

  /**
   * Returns a running job to the queue because its attempt was interrupted (worker stopped or killed).
   * The interrupted attempt is not counted, so the job's next attempt uses the same number.
   * Returns the number of jobs requeued.
   */
  requeueRunning(): number {
    const result = this.db
      .prepare(
        `UPDATE jobs SET status = 'queued', attempts = attempts - 1, completed_steps = 0, run_after = 0, updated_at = ?
         WHERE status = 'running'`,
      )
      .run(new Date().toISOString());
    return Number(result.changes);
  }

  interrupt(id: string): void {
    this.db
      .prepare(
        `UPDATE jobs SET status = 'queued', attempts = attempts - 1, completed_steps = 0, run_after = 0, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      )
      .run(new Date().toISOString(), id);
  }

  heartbeat(now: number): void {
    this.db
      .prepare(`INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`)
      .run(now);
  }

  clearHeartbeat(): void {
    this.db.prepare(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
  }

  workerUp(now: number): boolean {
    const row = this.db.prepare(`SELECT at FROM heartbeats WHERE name = 'worker'`).get() as unknown as { at: number } | undefined;
    return row !== undefined && now - row.at <= HEARTBEAT_STALE_MS;
  }
}

