import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { JobStore } from './store.ts';
import { MAX_BODY_BYTES, parseSubmission, type FieldError } from './validate.ts';

const db = openDatabase();
const store = new JobStore(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

const notFound = (res: ServerResponse) => sendError(res, 404, 'not_found', 'No such resource.');
const methodNotAllowed = (req: IncomingMessage, res: ServerResponse) => {
  req.resume();
  sendError(res, 405, 'method_not_allowed', `${req.method} is not allowed here.`);
};

/** Reads the body, or resolves to null when it is larger than MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size <= MAX_BODY_BYTES) chunks.push(chunk);
      else tooLarge = true;
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const rawKey = req.headers['idempotency-key'];
  const parsed = parseSubmission(req.headers['content-type'], body, typeof rawKey === 'string' ? rawKey : undefined);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', parsed.fields);
    return;
  }
  const { value, key } = parsed;
  const fingerprint = JSON.stringify([value.input, value.steps, value.failAttempts]);
  const outcome = store.createJob(value, key === undefined ? undefined : { key, fingerprint });
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(req, res);
    sendJson(res, 200, { status: 'ok', worker: store.workerUp(Date.now()) ? 'up' : 'down' });
    return;
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(req, res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: store.listJobs() });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(req, res);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(req, res);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound(res);
    }
    const job = store.getJob(id);
    return job ? sendJson(res, 200, job) : notFound(res);
  }

  req.resume();
  notFound(res);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

