import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { JobStore, MAX_ATTEMPTS, type Job } from './store.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
const store = new JobStore(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

// A previous worker that died mid-attempt left jobs as "running". Requeue them: they run again.
const requeued = store.requeueRunning();
if (requeued > 0) console.log(`requeued ${requeued} interrupted job(s)`);

store.heartbeat(Date.now());
const heartbeat = setInterval(() => store.heartbeat(Date.now()), HEARTBEAT_MS);

/** Runs one attempt of a job. The attempt number is `job.attempts`, already counted when claimed. */
async function runAttempt(job: Job): Promise<void> {
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      store.interrupt(job.id);
      return;
    }
    if (attempt <= job.failAttempts) {
      // Simulated transient failure: it happens at the first step, before any progress.
      if (attempt < MAX_ATTEMPTS) store.scheduleRetry(job.id, Date.now() + RETRY_DELAY_MS);
      else store.failJob(job.id, 'transient failure');
      return;
    }
    store.setProgress(job.id, step);
  }
  store.completeJob(job.id, job.input.toUpperCase());
}

console.log('worker started');
while (!stopping) {
  const job = store.claimNext(Date.now());
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeat);
store.clearHeartbeat();
db.close();
console.log('worker stopped');

